// Las fechas llegan de la API en hora UTC del servidor, sin zona
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fecha = d => d ? new Date(String(d).endsWith('Z') ? d : d + 'Z').toLocaleString('es-ES', { timeZone: 'Europe/Madrid', dateStyle: 'short', timeStyle: 'short' }) : '—';
const idioma = l => ({ es: 'castellano', ca: 'catalán' }[l] || '—');
const fila = (k, v) => `<tr><td style="padding:4px 12px 4px 0;color:#64748b">${k}</td><td style="padding:4px 0;color:#0f172a">${v}</td></tr>`;
const ficha = c => `<table style="border-collapse:collapse;font-size:14px">
  ${fila('Negocio', `<b>${esc(c.name)}</b>${c.city ? ' · ' + esc(c.city) : ''}`)}
  ${fila('Contacto', esc(c.adminName) || '—')}
  ${fila('Email', c.adminEmail ? `<a href="mailto:${esc(c.adminEmail)}">${esc(c.adminEmail)}</a>` : '—')}
  ${fila('Teléfono', esc(c.phone) || '—')}
  ${fila('Idioma', idioma(c.language))}
  ${fila('Email verificado', c.emailVerified ? 'sí' : 'no')}
  ${fila('Registro', fecha(c.createdAt))}
  ${fila('Fin de la prueba', c.trialEndsAt ? fecha(c.trialEndsAt) : 'cliente de pago')}
</table>`;
const plantilla = (titulo, cuerpo) => `<div style="font-family:Arial,sans-serif;max-width:640px;color:#0f172a">
  <h2 style="margin:0 0 12px">${titulo}</h2>${cuerpo}
  <p style="margin-top:24px;font-size:12px;color:#94a3b8">Alerta interna de PedidAI generada por n8n.</p></div>`;

const c = $input.first().json.body || {};
const html = plantilla('Nuevo registro en PedidAI', ficha(c) +
  '<p style="margin-top:16px">Los primeros días deciden si se queda: escríbele o llámale para ayudarle a subir sus primeros albaranes.</p>');
return [{ json: { subject: `Nuevo registro: ${c.name || 'sin nombre'}${c.city ? ' (' + c.city + ')' : ''}`, html } }];
